#### C2. Missing Input Validation on Profile IDs
**Files:** `working_profile_manager.mjs:140-200`, `working_profiles.py:110-170`  
**Severity:** Critical  
**Failure Mechanism:** `workingProfileId` and `reasoningModeId` parameters are used directly in file operations and HTTP requests without validation, enabling:
- Path injection via crafted profile IDs
- HTTP header injection via mode IDs
- Potential SSRF if profile IDs are used in URLs

**Refactored Code (Node.js):**
```javascript
const PROFILE_ID_PATTERN = /^[a-zA-Z0-9_-]{1,64}$/;
const MODE_ID_PATTERN = /^[a-zA-Z0-9_-]{1,64}$/;

function validateProfileId(profileId) {
  if (!profileId || typeof profileId !== 'string') {
    throw new Error('Profile ID must be a non-empty string');
  }
  if (profileId.length > 64) {
    throw new Error('Profile ID exceeds maximum length of 64 characters');
  }
  if (!PROFILE_ID_PATTERN.test(profileId)) {
    throw new Error(`Invalid profile ID format: ${profileId}`);
  }
  return profileId;
}

function validateModeId(modeId) {
  if (!modeId || typeof modeId !== 'string') {
    throw new Error('Mode ID must be a non-empty string');
  }
  if (modeId.length > 64) {
    throw new Error('Mode ID exceeds maximum length of 64 characters');
  }
  if (!MODE_ID_PATTERN.test(modeId)) {
    throw new Error(`Invalid mode ID format: ${modeId}`);
  }
  return modeId;
}

export async function switchWorkingProfile(workingProfileId, reasoningModeId = null, updatedBy = "api") {
  // Validate inputs first
  workingProfileId = validateProfileId(workingProfileId);
  if (reasoningModeId) {
    reasoningModeId = validateModeId(reasoningModeId);
  }
  if (updatedBy && typeof updatedBy === 'string' && updatedBy.length > 64) {
    updatedBy = updatedBy.substring(0, 64);
  }

  // ... rest of function
}
```

**Refactored Code (Python):**
```python
import re

PROFILE_ID_PATTERN = re.compile(r'^[a-zA-Z0-9_-]{1,64}$')
MODE_ID_PATTERN = re.compile(r'^[a-zA-Z0-9_-]{1,64}$')

def validate_profile_id(profile_id: str) -> str:
    """Validate profile ID format and length"""
    if not profile_id or not isinstance(profile_id, str):
        raise ValueError("Profile ID must be a non-empty string")
    if len(profile_id) > 64:
        raise ValueError("Profile ID exceeds maximum length of 64 characters")
    if not PROFILE_ID_PATTERN.match(profile_id):
        raise ValueError(f"Invalid profile ID format: {profile_id}")
    return profile_id

def validate_mode_id(mode_id: str) -> str:
    """Validate mode ID format and length"""
    if not mode_id or not isinstance(mode_id, str):
        raise ValueError("Mode ID must be a non-empty string")
    if len(mode_id) > 64:
        raise ValueError("Mode ID exceeds maximum length of 64 characters")
    if not MODE_ID_PATTERN.match(mode_id):
        raise ValueError(f"Invalid mode ID format: {mode_id}")
    return mode_id

def switch_working_profile(working_profile_id: str, reasoning_mode_id: str = None, updated_by: str = "api") -> dict:
    """Safely switches the global Working Profile with strict validation"""
    # Validate inputs first
    working_profile_id = validate_profile_id(working_profile_id)
    if reasoning_mode_id:
        reasoning_mode_id = validate_mode_id(reasoning_mode_id)
    if updated_by and isinstance(updated_by, str) and len(updated_by) > 64:
        updated_by = updated_by[:64]

    # ... rest of function
```

