#### C3. HTTP Response DoS via Unbounded Body Accumulation
**Files:** `working_profile_manager.mjs:100-130`, `working_profiles.py:80-100`  
**Severity:** Critical  
**Failure Mechanism:** Response bodies are accumulated without size limits, enabling memory exhaustion attacks if Agent Server returns large error responses.

**Node.js Vulnerability:**
```javascript
let body = "";
res.on("data", (chunk) => {
  body += chunk;  // Unbounded string concatenation
});
```

**Python Vulnerability:**
```python
body = ""
try:
    body = e.read().decode("utf-8", errors="ignore")  # No size limit
```

**Refactored Code (Node.js):**
```javascript
const MAX_RESPONSE_SIZE = 65536; // 64KB max response

export async function syncToAgentServer(agentProfileId, llmProfileName) {
  const apiKey = getSessionApiKey();
  const payload = JSON.stringify({
    active_agent_profile_id: agentProfileId,
    active_profile: llmProfileName,
  });

  return new Promise((resolve, reject) => {
    let body = "";
    let bodySize = 0;

    const req = httpRequest(
      {
        hostname: "127.0.0.1",
        port: AGENT_SERVER_PORT,
        path: "/api/settings",
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(payload),
          "x-session-api-key": apiKey,
        },
        timeout: 5000,
      },
      (res) => {
        res.on("data", (chunk) => {
          bodySize += chunk.length;
          if (bodySize > MAX_RESPONSE_SIZE) {
            res.destroy(new Error("Response size exceeded limit"));
            return;
          }
          body += chunk;
        });

        res.on("end", () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            resolve({ ok: true, status: res.statusCode, body });
          } else {
            resolve({ ok: false, status: res.statusCode, body });
          }
        });
      }
    );

    req.on("error", (err) => {
      reject(err);
    });

    req.on("timeout", () => {
      req.destroy(new Error("Request timeout"));
      reject(new Error("Request timeout"));
    });

    req.write(payload);
    req.end();
  });
}
```

**Refactored Code (Python):**
```python
MAX_RESPONSE_SIZE = 65536  # 64KB max response

def sync_to_agent_server(agent_profile_id: str, llm_profile_name: str) -> tuple:
    api_key = get_session_api_key()
    payload = json.dumps({
        "active_agent_profile_id": agent_profile_id,
        "active_profile": llm_profile_name
    }).encode("utf-8")

    req = urllib.request.Request(
        AGENT_SERVER_URL,
        data=payload,
        headers={
            "Content-Type": "application/json",
            "x-session-api-key": api_key
        },
        method="PATCH"
    )

    try:
        with urllib.request.urlopen(req, timeout=5) as res:
            # Limit response size
            body = res.read(MAX_RESPONSE_SIZE)
            if len(body) == MAX_RESPONSE_SIZE:
                raise RuntimeError("Response size exceeded limit")

            if 200 <= res.status < 300:
                return True, ""
            return False, f"HTTP {res.status}"
    except urllib.error.HTTPError as e:
        body = ""
        try:
            body = e.read(MAX_RESPONSE_SIZE).decode("utf-8", errors="ignore")
            if len(body) == MAX_RESPONSE_SIZE:
                raise RuntimeError("Response size exceeded limit")
        except Exception:
            pass
        return False, f"HTTP {e.code}: {body or e.reason}"
    except Exception as e:
        return False, str(e)
```

