#### H2. Missing File Permission Validation for API Key
**Files:** `working_profile_manager.mjs:18-22`, `working_profiles.py:18-22`  
**Severity:** High  
**Failure Mechanism:** API key file permissions are not validated, allowing other users/processes to read sensitive credentials.

**Refactored Code (Node.js):**
```javascript
import { access, constants } from "node:fs/promises";

export async function getSessionApiKey() {
  try {
    if (!existsSync(API_KEY_FILE)) {
      return "";
    }

    // Check file permissions (owner read/write only)
    const stats = statSync(API_KEY_FILE);
    if (stats.mode & 0o077) {  // Check if group/other have any permissions
      console.warn("[WorkingProfileManager] API key file has insecure permissions");
      // Optionally fix permissions
      try {
        chmodSync(API_KEY_FILE, 0o600);
      } catch {}
    }

    const key = await access(API_KEY_FILE, constants.R_OK)
      ? readFileSync(API_KEY_FILE, "utf-8").trim()
      : "";

    return key;
  } catch (err) {
    console.warn("[WorkingProfileManager] Error reading API key:", err.message);
    return "";
  }
}
```

**Refactored Code (Python):**
```python
import stat

def get_session_api_key() -> str:
    if not os.path.exists(API_KEY_FILE):
        return ""

    # Check file permissions (owner read/write only)
    try:
        file_stat = os.stat(API_KEY_FILE)
        if file_stat.st_mode & 0o077:  # Check if group/other have any permissions
            print(f"[WorkingProfiles] API key file has insecure permissions")
            # Optionally fix permissions
            try:
                os.chmod(API_KEY_FILE, 0o600)
            except OSError:
                pass
    except OSError:
        pass

    try:
        with open(API_KEY_FILE, encoding="utf-8") as f:
            return f.read().strip()
    except Exception:
        pass
    return ""
```

