};

function validateProfile(data, filename) {
  if (!data || typeof data !== "object") {
    console.warn(`[WorkingProfileManager] Invalid profile in ${filename}: not an object`);
    return false;
  }

  if (typeof data.id !== "string" || !data.id || data.id.length > 64) {
    console.warn(`[WorkingProfileManager] Invalid profile in ${filename}: invalid id`);
    return false;
  }

