```

**Refactored Code (Python):**
```python
def validate_profile(data: dict, filename: str) -> bool:
    """Validate profile JSON structure"""
    if not isinstance(data, dict):
        print(f"[WorkingProfiles] Invalid profile {filename}: not a dict")
        return False

    if not isinstance(data.get("id"), str) or not data["id"] or len(data["id"]) > 64:
        print(f"[WorkingProfiles] Invalid profile {filename}: invalid id")
        return False

    if not isinstance(data.get("name"), str) or not data["name"] or len(data["name"]) > 256:
        print(f"[WorkingProfiles] Invalid profile {filename}: invalid name")
        return False

    return True

def load_working_profiles() -> list:
    seed_templates_if_missing()
    profiles = []
    if not os.path.exists(WORKING_PROFILES_DIR):
        return profiles
    for filename in sorted(os.listdir(WORKING_PROFILES_DIR)):
        if filename.endswith(".json"):
            filepath = os.path.join(WORKING_PROFILES_DIR, filename)
            try:
                with open(filepath, encoding="utf-8") as f:
                    data = json.load(f)
                    if validate_profile(data, filename):
                        profiles.append(data)
                    else:
                        print(f"[WorkingProfiles] Skipping invalid profile {filename}")
            except Exception as e:
                print(f"[WorkingProfiles] Error loading {filename}: {e}")
    return profiles
```

